<script lang="ts">
 import {onMount} from 'svelte';import {language} from './i18n';import {catalog} from './catalog';import {importGlb} from './assetGeometry';import {uid} from './scene';import {lengthMm} from './editing';
 export interface PersonalItem {id:string;name:string;catalogId:string;width:number;depth:number;height:number;color:string;brand:string;model:string;sourceUrl:string;image:string;asset?:{name:string;data:string;license:string};}
 let {onadd}:{onadd:(item:PersonalItem)=>void}=$props();
 const say=(a:string,b:string)=>$language==='zh'?a:b;
 let items=$state<PersonalItem[]>([]),name=$state(''),base=$state('desk'),width=$state('1200mm'),depth=$state('600mm'),height=$state('750mm'),brand=$state(''),model=$state(''),sourceUrl=$state(''),image=$state(''),license=$state('User provided'),asset=$state<PersonalItem['asset']>(),unit=$state<'m'|'cm'|'mm'>('m'),turns=$state(0),busy=$state(false),message=$state(''),glbFile=$state<File>(),editing=$state('');
 const api=()=>typeof window!=='undefined'?(window as any).roomfit:null;
 onMount(()=>{void(async()=>{try{const data=api()?await api().preferences():JSON.parse(localStorage.getItem('roomfit-settings')||'{}');items=data.personal||[];}catch(e){message=String(e);}})();});
 async function persist(next:PersonalItem[]){if(JSON.stringify(next).length>32e6)throw new Error('Library exceeds 32 MB');if(api())await api().preferences({personal:next});else{const p=JSON.parse(localStorage.getItem('roomfit-settings')||'{}');localStorage.setItem('roomfit-settings',JSON.stringify({...p,personal:next}));}items=next;}
 async function importModel(){if(!glbFile)return;busy=true;message='';try{const a=await importGlb(glbFile,unit,turns);asset={name:glbFile.name,data:a.data,license};width=`${a.width}mm`;depth=`${a.depth}mm`;height=`${a.height}mm`;message=`${a.parts} meshes / ${a.vertices} vertices · ${say('已归正中心与地面，保持原始比例','Centered and grounded; original proportions retained')}`;}catch(e){asset=undefined;message=String(e);}finally{busy=false;}}
 async function save(){try{if(!name.trim())throw new Error(say('请输入名称','Enter a name'));const next:PersonalItem={id:editing||uid(),name,catalogId:base,width:lengthMm(width),depth:lengthMm(depth),height:lengthMm(height),color:'#b9a58c',brand,model,sourceUrl,image,...(asset?{asset:{...asset,license}}:{})};if([next.width,next.depth,next.height].some(n=>n<=0))throw new Error('Invalid dimensions');await persist([...items.filter(i=>i.id!==next.id),next]);message=say('已保存到本机个人家具库','Saved to local personal library');editing='';}catch(e){message=String(e);}}
 function edit(i:PersonalItem){editing=i.id;name=i.name;base=i.catalogId;width=`${i.width}mm`;depth=`${i.depth}mm`;height=`${i.height}mm`;brand=i.brand;model=i.model;sourceUrl=i.sourceUrl;image=i.image;asset=i.asset;license=i.asset?.license||'User provided';}
</script>
<details class="personal"><summary>{say('我的家具 · 跨工程保存','My furniture · saved across projects')} ({items.length})</summary>
 <div class="saved">{#each items as item}<article>{#if item.image}<img src={item.image} alt=""/>{/if}<b>{item.name}</b><small>{Math.round(item.width)}×{Math.round(item.depth)}×{Math.round(item.height)} mm</small><div><button onclick={()=>onadd(item)}>{say('添加','Add')}</button><button onclick={()=>edit(item)}>{say('编辑','Edit')}</button><button onclick={async()=>{try{await persist(items.filter(i=>i.id!==item.id));}catch(e){message=String(e);}}}>×</button></div></article>{/each}</div>
 <h4>{say('登记自己的家具','Register your furniture')}</h4><label>{say('名称','Name')}<input aria-label={say('个人家具名称','Personal furniture name')} bind:value={name}/></label><label>{say('通用结构','Generic structure')}<select bind:value={base} onchange={()=>{const c=catalog.find(c=>c.id===base)!;width=String(c.w);depth=String(c.d);height=String(c.h);asset=undefined;}}>{#each catalog as c}<option value={c.id}>{$language==='zh'?c.name:c.en}</option>{/each}</select></label>
 <div class="sizes"><label>{say('宽','Width')}<input bind:value={width}/></label><label>{say('深','Depth')}<input bind:value={depth}/></label><label>{say('高','Height')}<input bind:value={height}/></label></div>
 <label>{say('商品照片（仅资料）','Product photo (reference)')}<input type="file" accept="image/png,image/jpeg,image/webp" onchange={async e=>{const f=e.currentTarget.files?.[0];if(!f)return;try{if(f.size>2e6)throw new Error('Photo exceeds 2 MB');const bitmap=await createImageBitmap(f),c=document.createElement('canvas'),scale=Math.min(1,600/Math.max(bitmap.width,bitmap.height));c.width=Math.round(bitmap.width*scale);c.height=Math.round(bitmap.height*scale);c.getContext('2d')!.drawImage(bitmap,0,0,c.width,c.height);bitmap.close();image=c.toDataURL('image/jpeg',.85);}catch(e){message=String(e);}}}/></label>
 <details><summary>{say('导入自己的 GLB','Import your GLB')}</summary><p>{say('支持无贴图、无动画、内嵌纯 PBR 模型。导入后保持比例。','Embedded solid PBR models without textures or animation. Proportions are preserved.')}</p><input aria-label="GLB" type="file" accept=".glb" onchange={e=>glbFile=e.currentTarget.files?.[0]}/><div class="sizes"><select aria-label={say('GLB 单位','GLB units')} bind:value={unit}><option>m</option><option>cm</option><option>mm</option></select><select aria-label={say('GLB 朝向','GLB orientation')} bind:value={turns}><option value={0}>0°</option><option value={1}>90°</option><option value={2}>180°</option><option value={3}>270°</option></select></div><label>{say('模型来源与许可','Model source and license')}<input bind:value={license}/></label><button disabled={busy||!glbFile} onclick={importModel}>{busy?say('读取中…','Loading…'):say('检查并读取模型','Inspect and load model')}</button></details>
 <label>{say('品牌','Brand')}<input bind:value={brand}/></label><label>{say('型号','Model')}<input bind:value={model}/></label><label>{say('商品链接','Product link')}<input bind:value={sourceUrl}/></label><button disabled={busy} onclick={save}>{say('保存到我的家具','Save to my furniture')}</button><p role="status">{message}</p>
</details>
<style>.personal{padding:15px;color:#294235;border-top:1px solid #d4dfcc;font-size:12px}.personal summary{cursor:pointer;font-weight:500;margin:8px 0}label{display:flex;flex-direction:column;gap:4px;margin:9px 0;font-size:11px}input,select,button{box-sizing:border-box;width:100%;min-width:0;padding:7px;border:1px solid #c4d2ba;color:#2e493a;background:#fffef9;border-radius:5px;font:inherit}button{cursor:pointer}p,small{font-size:10px;line-height:1.7;color:#52674e}.sizes{display:flex;gap:5px}.sizes>*{width:33%}.saved{display:grid;gap:8px}.saved article{padding:8px;background:#edf2e6;border-radius:5px}.saved img{width:100%;height:80px;object-fit:contain}.saved b,.saved small{display:block}.saved article div{display:flex;gap:3px;margin-top:5px}</style>
